(function(){
  var P = AutoJS.players()[0];
  var Cur = Java.loadClass('com.merlinkitsune.astral_dice.compat.curios.CuriosApi');
  var CSU = Java.loadClass('com.merlinkitsune.astral_dice.item.CurioSlotUtil');
  var SC = Java.loadClass('com.merlinkitsune.astral_dice.compat.curios.SlotContext');
  var NLI = Java.loadClass('com.merlinkitsune.astral_dice.item.sign.NancyLuSignItem');
  var MSI = Java.loadClass('com.merlinkitsune.astral_dice.item.sign.MosesSignItem');
  var ItemStack = Java.loadClass('net.minecraft.world.item.ItemStack');
  AutoJS.command('kill @e[type=!player,distance=..48]');
  AutoJS.command('clear @a');
  AutoJS.command('effect clear @a');
  var inv = Cur.getCuriosInventory(P).get();
  var diceH = inv.getStacksHandler('dice').get();
  var standH = inv.getStacksHandler('stand').get();
  diceH.getStacks().setStackInSlot(0, ItemStack.EMPTY);
  standH.getStacks().setStackInSlot(0, ItemStack.EMPTY);
  var sign = AutoJS.stack('astral_dice:nancy_lu_sign', 1);
  var signItem = sign.getItem();
  var out = {};
  out.canEquipStand = signItem.canEquip(new SC(P, 'stand', 0), sign);
  out.canEquipDice = signItem.canEquip(new SC(P, 'dice', 0), sign);
  out.hasDiceBefore = CSU.hasDiceEquipped(P);
  out.signEquippedBefore = NLI.isEquipped(P);
  var res1 = CSU.tryAutoEquip(P, AutoJS.stack('astral_dice:nancy_lu_sign', 1), 'stand');
  out.equipWithoutDiceOk = res1.getResult().consumesAction();
  out.standSlotAfterAttempt = standH.getStacks().getStackInSlot(0).isEmpty() ? 'empty' : String(AutoJS.id(standH.getStacks().getStackInSlot(0)));
  CSU.tryAutoEquip(P, AutoJS.stack('astral_dice:diamond_dice', 1), 'dice');
  out.hasDiceAfter = CSU.hasDiceEquipped(P);
  var res2 = CSU.tryAutoEquip(P, AutoJS.stack('astral_dice:nancy_lu_sign', 1), 'stand');
  out.equipWithDiceOk = res2.getResult().consumesAction();
  out.signEquippedAfter = NLI.isEquipped(P);
  out.mosesEquippedAfter = MSI.isEquipped(P);
  out.standSlotId = standH.getStacks().getStackInSlot(0).isEmpty() ? 'empty' : String(AutoJS.id(standH.getStacks().getStackInSlot(0)));
  out.enderPearlImmuneTicks = NLI.ENDER_PEARL_IMMUNE_TICKS;
  return out;
})()

(function(){
  var P = AutoJS.players()[0];
  var Cur = Java.loadClass('com.merlinkitsune.astral_dice.compat.curios.CuriosApi');
  var DCI = Java.loadClass('com.merlinkitsune.astral_dice.item.dice.DiceCurioItem');
  var ItemStack = Java.loadClass('net.minecraft.world.item.ItemStack');
  var inv = Cur.getCuriosInventory(P).get();
  inv.getStacksHandler('dice').get().getStacks().setStackInSlot(0, ItemStack.EMPTY);
  inv.getStacksHandler('stand').get().getStacks().setStackInSlot(0, ItemStack.EMPTY);
  DCI.refreshChipSlotCount(P);
  AutoJS.command('clear @a');
  AutoJS.command('effect clear @a');
  return {
    diceSlotEmptyAfter: inv.getStacksHandler('dice').get().getStacks().getStackInSlot(0).isEmpty(),
    standSlotEmptyAfter: inv.getStacksHandler('stand').get().getStacks().getStackInSlot(0).isEmpty(),
    chipSlotsFinal: inv.getStacksHandler('chip').get().getSlots()
  };
})()
